create table if not exists users (id serial primary key,name text not null,phone text not null unique,email text unique,password_hash text not null,role text not null default 'client' check(role in ('client','restaurant_owner','driver','admin')),loyalty_points integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists restaurants (id serial primary key,name text not null,type text not null,description text,address text not null,city text not null,lat real,lng real,phone text not null,email text,opening_hours text not null,image_url text,status text not null default 'pending' check(status in ('pending','approved','suspended')),rating real,review_count integer not null default 0,owner_id integer not null references users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists dishes (id serial primary key,restaurant_id integer not null references restaurants(id) on delete cascade,name text not null,description text,price real not null,category text not null,image_url text,available boolean not null default true,has_promotion boolean not null default false,promotion_price real,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists orders (id serial primary key,tracking_token text unique,customer_id integer references users(id),guest_name text,guest_phone text,restaurant_id integer not null references restaurants(id),restaurant_name text not null,items jsonb not null,status text not null default 'pending' check(status in ('pending','confirmed','preparing','ready','delivering','delivered','cancelled')),subtotal real not null,delivery_fee real not null default 1500,discount real not null default 0,total real not null,delivery_address text not null,delivery_city text not null,delivery_lat real,delivery_lng real,delivery_zone_id integer,delivery_distance_km real,payment_method text not null check(payment_method in ('orange_money','moov_money','cash')),payment_status text not null default 'pending' check(payment_status in ('pending','paid','failed','refunded')),loyalty_points_earned integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists addresses (id serial primary key,user_id integer not null references users(id) on delete cascade,label text not null,address text not null,city text not null,is_default boolean not null default false,created_at timestamptz not null default now());
create table if not exists loyalty_history (id serial primary key,user_id integer not null references users(id) on delete cascade,order_id integer references orders(id),points integer not null,description text not null,created_at timestamptz not null default now());
create table if not exists drivers (id serial primary key,user_id integer not null unique references users(id) on delete cascade,is_available boolean not null default false,is_online boolean not null default false,current_lat real,current_lng real,current_city text,vehicle_type text,vehicle_plate text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists delivery_assignments (id serial primary key,order_id integer not null unique references orders(id) on delete cascade,driver_id integer references drivers(id) on delete set null,status text not null default 'pending' check(status in ('pending','assigned','accepted','picked_up','delivering','delivered','cancelled')),assigned_at timestamptz,accepted_at timestamptz,picked_up_at timestamptz,delivered_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists delivery_zones (id serial primary key,name text not null unique,city text not null,base_fee real not null default 1000,price_per_km real not null default 0,max_distance_km real,is_active boolean not null default true,priority integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_restaurants_owner_id on restaurants(owner_id);
create index if not exists idx_dishes_restaurant_id on dishes(restaurant_id);
create index if not exists idx_orders_customer_id on orders(customer_id);
create index if not exists idx_orders_restaurant_id on orders(restaurant_id);
create index if not exists idx_orders_status on orders(status);
create index if not exists idx_addresses_user_id on addresses(user_id);
create index if not exists idx_loyalty_history_user_id on loyalty_history(user_id);
create index if not exists idx_delivery_assignments_driver_id on delivery_assignments(driver_id);
create index if not exists idx_delivery_zones_city_active on delivery_zones(city,is_active);
alter table users enable row level security; alter table restaurants enable row level security; alter table dishes enable row level security; alter table orders enable row level security; alter table addresses enable row level security; alter table loyalty_history enable row level security; alter table drivers enable row level security; alter table delivery_assignments enable row level security; alter table delivery_zones enable row level security;